Definition oblk (p dt cd ad : Z) (q : word) : Prop :=
  p <> 0%Z /\ (q = Z_to_bv 64 p \/ q = Z_to_bv 64 dt \/ (cd <> 0%Z /\ (q = Z_to_bv 64 cd \/ q = Z_to_bv 64 ad))).

Definition ocm (C : lctx) (A : AS) (m : word -> option byte) (p dt cd ad : Z) (cv : cmapv) : Prop :=
  cd = 0%Z \/
  (cd <> 0%Z /\ CMAPat m cd cv /\ cmap_ok cv /\ c_arr cv = ad /\ (cd + 24 <= alloc_top (c_vm C))%Z /\ (1 <= ad)%Z /\ (ad + 4 * c_nalloc cv <= alloc_top (c_vm C))%Z /\
   live (c_A0 C) (Z_to_bv 64 cd) = None /\ live (c_A0 C) (Z_to_bv 64 ad) = None /\
   live A (Z_to_bv 64 cd) = Some 24%Z /\ live A (Z_to_bv 64 ad) = Some (4 * c_nalloc cv)%Z /\ (0 < 4 * c_nalloc cv)%Z /\
   cd <> ad /\ cd <> p /\ ad <> p /\ dt <> cd /\ dt <> ad).

Definition opix (C : lctx) (A : AS) (m : word -> option byte) (p w h d cd dt ad : Z) (cv : cmapv) : Prop :=
  p = 0%Z \/
  ((4096 <= p)%Z /\ (p + 64 <= alloc_top (c_vm C))%Z /\ (4096 <= dt)%Z /\ (dt + 4 * (wpl_of w d * h) <= alloc_top (c_vm C))%Z /\ p <> dt /\
   hdr_ok w h d /\ (1 <= w)%Z /\ (1 <= h)%Z /\
   live (c_A0 C) (Z_to_bv 64 p) = None /\ live (c_A0 C) (Z_to_bv 64 dt) = None /\
   live A (Z_to_bv 64 p) = Some 64%Z /\ live A (Z_to_bv 64 dt) = Some (4 * (wpl_of w d * h))%Z /\
   PIXat m p (hdv w h d cd dt) /\ ocm C A m p dt cd ad cv).

