Lemma copy_opix : forall C A A' m' regs' (w h d cm : Z) (cv : cmapv), hdr_ok w h d -> (1 <= w)%Z -> (1 <= h)%Z ->
  ((getr regs' 10 = Z_to_bv 64 0 /\ forall q, live A' q = live A q)
   \/ (exists pixd cd data, getr regs' 10 = Z_to_bv 64 pixd /\ pixt_new C A A' m' pixd w h d cd data cv)) ->
  exists c cdc dtc adc, getr regs' 10 = Z_to_bv 64 c /\ (0 <= c < 2 ^ 64)%Z /\
    opix C A' m' c w h d cdc dtc adc (CMAPV adc (c_d cv) (c_nalloc cv) (c_n cv) 0) /\
    (forall q, ~ oblk c dtc cdc adc q -> live A' q = live A q) /\ (forall b, oblk c dtc cdc adc b -> live A b = None /\ live A' b <> None).
Proof.
