(* [comment removed for export] *)
Lemma res_opix : forall C A A' m' regs' (w h d : Z), hdr_ok w h d -> (1 <= w)%Z -> (1 <= h)%Z ->
  ((getr regs' 10 = Z_to_bv 64 0 /\ forall q, live A' q = live A q)
   \/ (exists pixd datad, getr regs' 10 = Z_to_bv 64 pixd /\ pixr_new C A A' m' pixd datad (set_data (pix_hdr w h d) datad))) ->
  exists r dr, getr regs' 10 = Z_to_bv 64 r /\ (0 <= r < 2 ^ 64)%Z /\ opix C A' m' r w h d 0 dr 0 cmap0 /\
    (forall q, ~ oblk r dr 0 0 q -> live A' q = live A q) /\ (forall b, oblk r dr 0 0 b -> live A b = None /\ live A' b <> None).
