Lemma r1_sub16 : forall s k, (s mod 16 = 0)%Z -> (k mod 16 = 0)%Z -> ((s - k) mod 16 = 0)%Z.
Proof. intros s k H1 H2. rewrite Zminus_mod, H1, H2. reflexivity. Qed.

Lemma r1_sub8 : forall s k, (s mod 16 = 0)%Z -> (k mod 8 = 0)%Z -> ((s - k) mod 8 = 0)%Z.
Proof.
  intros s k H1 H2. apply Zmod_divides in H1 as [c ->]; [|lia]. apply Zmod_divides in H2 as [e ->]; [|lia].
  replace (16 * c - 8 * e)%Z with ((2 * c - e) * 8)%Z by ring. apply Z_mod_mult.
Qed.

Lemma r1_fs_notin : forall r : reg, In (u r) fs_list -> r <> 8%bv -> ~ In (Z.to_nat (u r)) [8; 10; 11]%nat.
Proof.
  intros r Hr N8 Hin. unfold fs_list in Hr. cbn [In] in Hr, Hin.
  assert (U : bv_unsigned r = 8%Z) by lia.
  apply N8. apply bv_eq. rewrite U. reflexivity.
Qed.

Lemma r1_slot : forall C A m md m' (lo : Z), Cok C -> W C A m md -> (c_top C - LSTK <= lo)%Z -> (lo + 8 <= c_top C)%Z ->
  rinv [(lo, 8%Z)] m m' ->
  W C A m' md /\ POSTM C A (lo + 8) m m' /\ (forall a : word, ~ (lo <= u a < lo + 8)%Z -> m' a = m a).
Proof.
  intros C A m md m' lo CK HW H1 H2 RI.
  assert (O : forall a : word, ~ (lo <= u a < lo + 8)%Z -> m' a = m a) by (intros a Ha; exact (rinv_out1 lo 8 m m' a RI Ha)).
  split; [|split; [|exact O]].
  - apply (W_local C A m md m' (lo + 8) CK HW H2); [| exact (proj1 RI)].
    intros a Ha. left. unfold scratch.
    destruct (Z_le_dec lo (u a)); destruct (Z_lt_dec (u a) (lo + 8)); try (exfalso; apply Ha; apply O; lia). lia.
  - apply (POSTM_range C A m md m' lo (lo + 8) (lo + 8) CK HW O); lia.
Qed.

Lemma r1_sv : forall C m m' s s' ret regs fr, Cok C -> FRM C s' m m' -> (c_top C - LSTK <= s')%Z -> (s' <= s - 32)%Z ->
  (s <= 2 ^ 64)%Z -> SAVED4 m s ret regs fr -> SAVED4 m' s ret regs fr.
Proof.
  intros C m m' s s' ret regs fr CK F H1 H2 H3 (S1 & S2 & S3 & S4). unfold SAVED4. rewrite <- p16_segs in *.
  rewrite (FRM_rdn_above C s' m m' (s - 8) 8 CK F), (FRM_rdn_above C s' m m' (s - 16) 8 CK F),
          (FRM_rdn_above C s' m m' (s - 24) 8 CK F), (FRM_rdn_above C s' m m' (s - 32) 8 CK F) by lia.
  tauto.
Qed.

Lemma r1_rdn_frm : forall C s' m m' (z : Z) bs, Cok C -> FRM C s' m m' -> (c_top C - LSTK <= s')%Z -> (s' <= z)%Z ->
