    intros q Br Bc. exact (SEPcr q Bc Br). }
  rewrite with_vmmaps_vmmaps in RT6.
  pose proof (RT6 _ _ Hrm3 (proj1 (aroom_nonneg _ _ _ _ Hrm3)) (proj2 (aroom_nonneg _ _ _ _ Hrm3))) as Hrm4. rewrite !Z.sub_0_r in Hrm4.
  apply (rz_reach _ _ _ _ _ (w_pure _ _ _ _ HW6) (fz_I al_rom (mkFP fr5 cs5) r7 m6 s ltac:(lia) ltac:(csr; reflexivity))).
  intros fin (r8 & M6 & -> & -> & I1 & I2 & I10 & AG8).
  replace (Z_to_bv 64 104492) with (104492 : word) by (apply bv_eq; reflexivity).
  apply (pixDestroy_opix_W (mkFP fr5 cs5) C A4 m6 (with_vmmaps vm4 md) r8 (s - 64) (s - 48) r w h d 0 dr 0 cmap0 _ S CK HW6 I2
           ltac:(rewrite <- Zminus_mod_idemp_l, Hs16; reflexivity) ltac:(rewrite Etop; unfold ALLOC_STACK; rewrite LV; lia) ltac:(rewrite Etop; lia)
           I1 ltac:(red; apply bv_eq; reflexivity) ltac:(csr; reflexivity) I10 ltac:(apply AL8; reflexivity) ltac:(lia) ltac:(rewrite Etop; lia) S48f OPr6).
  intros A5 m7 vm5 r9 HW7 CS9 DN7 DL7 PM7 Z48 OUT7 RT7. rewrite ?with_vmmaps_twice in HW7 |- *.
  destruct PM7 as [F7 L7]. replace (s - 48 + 8)%Z with (s - 40)%Z in F7 by lia.
  assert (SV7 : SAVED4 m7 s ret regs fr0) by (sv_frm SV6 F7 Etop Evm).
  assert (P40g : rdn SEGS m7 (Z_to_bv 64 (s - 40)) 8 = Some (Z_to_le_bytes 8 pixs)).
  { rewrite (FRM_rdn16 C (s - 40) m6 m7 (s - 40) 8 CK F7) by (rewrite ?Etop, ?LV; lia). exact P40f. }
  assert (OPp7 : opix C A5 m7 pixs w h d cd dt ad cv).
  { apply (opix_livk C A5 m6 m7); [|exact L7 | exact ATL]. apply (opix_live_out C A4 A5 m6 pixs w h d cd dt ad cv (oblk r dr 0 0) OPp6 DL7 SEPpr). }
  rewrite with_vmmaps_vmmaps in RT7.
  pose proof (RT7 _ _ Hrm4 (proj1 (aroom_nonneg _ _ _ _ Hrm4)) (proj2 (aroom_nonneg _ _ _ _ Hrm4))) as Hrm5. rewrite !Z.sub_0_r in Hrm5.
  apply (rz_reach _ _ _ _ _ (w_pure _ _ _ _ HW7) (fz_J al_rom (mkFP fr5 cs5) r9 m7 s ltac:(lia) ltac:(csr; reflexivity))).
  intros fin (r10 & M7 & -> & -> & J1 & J2 & J10 & AG10).
  replace (Z_to_bv 64 104492) with (104492 : word) by (apply bv_eq; reflexivity).
  apply (pixDestroy_opix_W (mkFP fr5 cs5) C A5 m7 (with_vmmaps vm5 md) r10 (s - 64) (s - 40) pixs w h d cd dt ad cv _ S CK HW7 J2
           ltac:(rewrite <- Zminus_mod_idemp_l, Hs16; reflexivity) ltac:(rewrite Etop; unfold ALLOC_STACK; rewrite LV; lia) ltac:(rewrite Etop; lia)
           J1 ltac:(red; apply bv_eq; reflexivity) ltac:(csr; reflexivity) J10 ltac:(apply AL8; reflexivity) ltac:(lia) ltac:(rewrite Etop; lia) P40g OPp7).
  intros A6 m8 vm6 r11 HW8 CS11 DN8 DL8 PM8 Z40 OUT8 RT8. rewrite ?with_vmmaps_twice in HW8 |- *.
  destruct PM8 as [F8' L8]. replace (s - 40 + 8)%Z with (s - 32)%Z in F8' by lia.
  assert (SV8 : SAVED4 m8 s ret regs fr0) by (sv_frm SV7 F8' Etop Evm).
  rewrite with_vmmaps_vmmaps in RT8.
  pose proof (RT8 _ _ Hrm5 (proj1 (aroom_nonneg _ _ _ _ Hrm5)) (proj2 (aroom_nonneg _ _ _ _ Hrm5))) as Hrm6. rewrite !Z.sub_0_r in Hrm6.
  destruct SV8 as (Q1 & Q2 & Q3 & Q4).
  apply (rz_reach _ _ _ _ _ (w_pure _ _ _ _ HW8) (fz_Z al_rom fr5 cs5 r11 m8 s ret ret (getr regs 8) (getr regs 9) _ Hz5 ltac:(lia) Hret eq_refl Q1 Q2 Q3 Q4 ltac:(csr; reflexivity))).
  intros fin (fr6 & cs6 & r12 & M8 & -> & Hz6 & -> & Z2 & Z10 & Z8 & Z9 & AG12 & FS6 & FK6).
  assert (LQf : forall q, live A6 q = live A q).
  { intros q. destruct (oblk_dec pixs dt cd ad q) as [Bp|Bp]; [rewrite (DN8 q Bp); symmetry; exact (NW1 q Bp)|].
    rewrite (DL8 q Bp). destruct (oblk_dec r dr 0 0 q) as [Br|Br].
    - rewrite (DN7 q Br). destruct (NWr q Br) as [N2 _].
      destruct (oblk_dec c dtc cdc adc q) as [Bc|Bc]; [exfalso; exact (SEPcr q Bc Br)|].
      rewrite (LQc q Bc), (LQ1 q Bp) in N2. symmetry. exact N2.
    - rewrite (DL7 q Br). destruct (oblk_dec c dtc cdc adc q) as [Bc|Bc].
      + rewrite (DN6 q Bc). destruct (NWc q Bc) as [N1 _]. rewrite (LQ1 q Bp) in N1. symmetry. exact N1.
      + rewrite (DL6 q Bc), (LQr q Br), (LQc q Bc), (LQ1 q Bp). reflexivity. }
  apply (KF (mkFP fr6 cs6) A6 m8 vm6 r12 _ _ Hz6 HW8 LQf Z10 ltac:(apply cs_kept_intro; csr; reflexivity) Hrm6); lia.
