Theorem lept_fuzz_call : @fuzz_call_contract AL CL ASR.
Proof.
  unfold fuzz_call_contract.
  intros fx A m md regs dptr size pl ret sp0 argv envp S Hz Hinv Hpure Henv Ha0 Ha1 Hsz Hsz26 Hlive Hpl Hempty Hal16 Hra Hret H3 H4 Hsp16 Htop Hsp0 Hsp0hi Hisw Hwin Hsev Hpmm Hhdl Hgot kR bR Hrm Hrk Hrb K.
  destruct fx as [fr cs]. cbn [fp_csr] in Hz.
  pose proof fuzz_calls_nonneg as FZc.
  pose proof (fuzz_margin_bound size ltac:(lia)) as FZm.
  rewrite p16_segs in Hhdl, K |- *. rewrite p16_tp in H4.
  pose proof (alloc_top_win_vals _ Hisw) as ATW. unfold sp_window_hi in Hsp0hi.
  pose proof (u64_range (getr regs 2)) as Hs. pose proof (u64_range dptr) as Hdp. pose proof (u64_range sp0) as Hsp0r.
  set (s := u (getr regs 2)) in *.
  assert (H2 : getr regs 2 = Z_to_bv 64 s) by (subst s; rewrite zbv_self; reflexivity). clearbody s.
  set (dp := u dptr) in *.
  assert (Edp : dptr = Z_to_bv 64 dp) by (subst dp; rewrite zbv_self; reflexivity). clearbody dp. rewrite Edp in Ha0, Hlive, Hempty.
  set (C := LCTX sp0 argv envp s (m_vmmaps md) m A).
  assert (Etop : c_top C = s) by reflexivity.
  pose proof LSTK_val as LV.
  assert (LSv : (LSTK <= LEPT_STACK)%Z) by (rewrite LV; unfold LEPT_STACK; lia).
  assert (LS64 : (64 <= LSTK)%Z) by (rewrite LV; lia).
  assert (CK : Cok C) by (constructor; cbn; rewrite ?LV; unfold LEPT_STACK in *; lia).
  assert (Hsr : (4096 + 64 <= s <= 2 ^ 47)%Z) by (unfold LEPT_STACK in *; lia).
  assert (SOK : store_ok SEGS m (Z_to_bv 64 (s - 64)) 64 = true).
  { rewrite <- p16_segs. apply store_ok_of_all; rewrite u_Z2bv by lia; [cbn; lia|]. intros x Hx. cbn in Hx.
    destruct (Hwin x ltac:(lia)) as (D & _). unfold wview. destruct (m x) eqn:E; [discriminate | exfalso; exact (D eq_refl)]. }
  assert (BLK : forall q k i, live A q = Some k -> (0 <= i < k)%Z -> owned A (at_ q i) /\ ~ (s - LEPT_STACK <= u (at_ q i) < s)%Z).
  { intros q k i L Hi. pose proof (ai_live_hull A m (m_vmmaps md) q k Hinv L) as (Hk0 & _ & _ & OWN). pose proof (round16_ge k Hk0).
    destruct (OWN i ltac:(lia)) as (Ho & _). split; [exact Ho|]. intros R. exact (proj1 (proj2 (Hwin _ R)) Ho). }
  destruct (Z_lt_ge_dec size 3) as [SM|BG].
  { apply (rz_reach SEGS _ md _ S Hpure (fz_small al_rom fr cs regs m s size ret Hz Hsr ltac:(lia) SOK H2 Ha1 Hra Hret)).
    intros fin (fr' & cs' & r1 & M' & -> & Hz' & RI & Q2 & Q10 & Q1 & Q8 & Q9 & AG & F8 & FO).
    assert (OUT : forall a : word, ~ (s - 64 <= u a < s)%Z -> M' a = m a).
    { intros a Ha. apply (rinv_out1 (s - 64) 64 m M' a RI). lia. }
    rewrite <- (with_vmmaps_same md). apply (K (mkFP fr' cs') A M' (m_vmmaps md) r1 Hz').
    - apply (ai_frame A m _ _ Hinv).
      + intros a Ho _. apply OUT. intros R. exact (proj1 (proj2 (Hwin a ltac:(lia))) Ho).
      + intros a _ Hx. exact (proj1 RI a Hx).
      + intros a _ Hx. destruct (Z_lt_ge_dec (u a) (s - 64)); [rewrite OUT in Hx by lia; exact Hx|].
        destruct (Z_lt_ge_dec (u a) s); [exact (proj1 (Hwin a ltac:(lia))) | rewrite OUT in Hx by lia; exact Hx].
    - intros q; reflexivity.
    - exact Q10.
    - apply cs_kept_intro; csr; reflexivity.
    - intros a _ _ _ _ NW. apply OUT. lia.
    - intros q k i L Hi. apply OUT. destruct (BLK q k i L Hi) as [_ X]. lia.
    - intros a Hx. right; right. exact (proj1 RI a Hx).
    - reflexivity. - reflexivity. - reflexivity. - reflexivity.
    - apply (aroom_mono _ _ _ _ _ _ Hrm); lia. }
  assert (Ldp : live A (Z_to_bv 64 dp) = Some size) by (apply Hlive; lia).
  assert (KF : forall (fx' : FPState) A' mf vm' rr kf bf, frm_zero (@fp_csr fx') -> W C A' mf (with_vmmaps vm' md) -> (forall q, live A' q = live A q) ->
               getr rr 10 = Z_to_bv 64 0 -> cs_kept regs rr -> aroom A' vm' kf bf -> (kR - FUZZ_CALLS <= kf)%Z -> (bR - fuzz_margin size <= bf)%Z ->
               realizes SEGS (mkCfg (@mkst fx' rr ret mf al_rom) (with_vmmaps vm' md)) S).
  { intros fx' A' mf vm' rr kf bf Hz' HWf LQ A0 CS HRf Hkf Hbf. apply (K fx' A' mf vm' rr Hz').
    - pose proof (w_inv _ _ _ _ HWf) as X. rewrite with_vmmaps_vmmaps in X. exact X.
    - exact LQ.
    - exact A0.
    - exact CS.
    - intros a N1 N2 N3 N4 N5. apply (w_frm _ _ _ _ HWf a); [exact N1 | exact N2 | exact N3 | unfold hcell; cbn; exact N4 | unfold scratch; rewrite ?Etop; lia].
    - intros q k i Lq Hi. exact (w_live0 _ _ _ _ HWf q k i Lq Hi).
    - intros a Hx. exact (w_def _ _ _ _ HWf a Hx).
    - destruct (w_vm _ _ _ _ HWf) as (VV1 & VV2 & VV3 & VV4). rewrite with_vmmaps_vmmaps in VV1. exact VV1.
    - destruct (w_vm _ _ _ _ HWf) as (VV1 & VV2 & VV3 & VV4). rewrite with_vmmaps_vmmaps in VV2. exact VV2.
    - destruct (w_vm _ _ _ _ HWf) as (VV1 & VV2 & VV3 & VV4). rewrite with_vmmaps_vmmaps in VV3. exact VV3.
    - destruct (w_vm _ _ _ _ HWf) as (VV1 & VV2 & VV3 & VV4). rewrite with_vmmaps_vmmaps in VV4. exact VV4.
    - apply (aroom_mono _ _ _ _ _ _ HRf); lia. }
  pose proof RK_pbl_val as RKv.
  assert (RKs : (RK_deser + 2 * RK_pixcopy + RK_pbl + RK_bbe <= FUZZ_CALLS)%Z)
    by (rewrite RKv; unfold RK_deser, RK_pixcopy, RK_pix, RK_cmapcopy, RK_bbe, FUZZ_CALLS; lia).
  assert (RK0 : (0 <= RK_deser /\ 0 <= RK_pixcopy /\ 0 <= RK_pbl /\ 0 <= RK_bbe)%Z)
    by (rewrite RKv; unfold RK_deser, RK_pixcopy, RK_pix, RK_cmapcopy, RK_bbe; lia).
  assert (RBm : (0 <= RB_deserT <= fuzz_margin size)%Z) by (rewrite RB_deserT_val; unfold fuzz_margin; lia).
  apply (fz_deser fr cs C A m md regs s dp size pl ret S kR bR CK Etop eq_refl eq_refl eq_refl Hz Hinv Hpure Henv H2 Hsp16 Hsr Hra Hret H4
           Ha0 Ha1 Hsz ltac:(lia) ltac:(lia) Hal16 Ldp Hpl Hwin Hsev Hpmm Hhdl Hgot Hrm ltac:(lia) ltac:(lia)).
  - intros fx' A' mf vm' rr kf bf Hzf HWf LQf R0 CS Hrf Hkf Hbf.
    apply (KF fx' A' mf vm' rr kf bf Hzf HWf LQf R0 CS Hrf); lia.
  - intros fr1 cs1 A1 m1 vm1 r1 pixs w h d cd dt ad cv Hz1 FR1 HW1 Y2 Y10 RR1 SV1 Hp NZ OP1 LQ1 NW1 Hrm1.
    destruct (opix_def C A1 m1 pixs w h d cd dt ad cv OP1 NZ) as (_ & _ & _ & _ & _ & HO & Hw & Hh & _).
    assert (FC : (RB_deserT + 2 * (RB_pixT (4 * (wpl_of w d * h)) + RB_cmapT cd) + RB_pbl w h d + RB_bbe w h d <= fuzz_margin size)%Z)
      by exact (proj2 (fuzz_covers w h d cd size HO Hw Hh)).
    assert (BB0 : (0 <= RB_bbe w h d)%Z) by exact (RB_bbe_nonneg w h d).
    pose proof (RB_pixT_nonneg (4 * (wpl_of w d * h))%Z) as RP0. pose proof (RB_cmapT_le cd) as RC0.
    pose proof (RB_pbl_nonneg w h d ltac:(lia)) as RBn.
    replace (Z_to_bv 64 (PC_FUZZ + 60)) with (Z_to_bv 64 97604) by reflexivity.
    apply (fz_round1 fr1 cs1 C A1 m1 (with_vmmaps vm1 md) r1 s pixs w h d cd dt ad cv ret regs fr S (kR - RK_deser)%Z (bR - RB_deserT)%Z
             CK Etop HW1 Hz1 Y2 ltac:(rewrite (RR1 4%bv) by in_lit; exact H4) Y10 OP1 NZ SV1
             ltac:(rewrite with_vmmaps_vmmaps; exact Hrm1) ltac:(lia) ltac:(lia)).
    intros fr2 cs2 A2 m2 vm2 r2 HW2 Hz2 Q2 Q9 RR2 Q8 F8 FS2 P40 OP2 LQ2 SV2 PM2 Hrm2.
    rewrite with_vmmaps_twice in HW2 |- *.
    replace (Z_to_bv 64 97684) with (Z_to_bv 64 (PC_FUZZ + 140)) by reflexivity.
    apply (fz_round2 fr2 cs2 fr C A A2 m2 md vm2 regs r2 s pixs w h d cd dt ad cv ret S
             (kR - RK_deser - (RK_pixcopy + RK_pbl))%Z (bR - RB_deserT - (RB_pixT (4 * (wpl_of w d * h)) + RB_cmapT cd + RB_pbl w h d))%Z
             CK Etop Hsp16 Hsr Hret H2 H4 Hz2 HW2 ltac:(rewrite Q2; exact Y2) Q8
             ltac:(intros x Hx; rewrite (RR2 x Hx); exact (RR1 x Hx)) F8 SV2 P40 Hp NZ OP2
             ltac:(intros q Hq; rewrite (LQ2 q); exact (LQ1 q Hq)) ltac:(intros q Hq; exact (proj1 (NW1 q Hq)))
             Hrm2 ltac:(lia) ltac:(lia)).
    intros fx' A' mf vm' rr kf bf Hzf HWf LQf R0 CS Hrf Hkf Hbf.
    apply (KF fx' A' mf vm' rr kf bf Hzf HWf LQf R0 CS Hrf); lia.
Qed.

